const { groupBy } = require('./group.js');

// Map each group key to how many items it holds.
function sizes(items, keyOf) {
  const groups = groupBy(items, keyOf);
  const out = {};
  for (const key of Object.keys(groups)) {
    out[key] = groups[key].length;
  }
  return out;
}

module.exports = { sizes };

