const assert = require('node:assert');
const { groupBy } = require('./group.js');
const { sizes } = require('./stats.js');

assert.deepStrictEqual(
  groupBy(['apple', 'ant', 'bee'], (w) => w[0]),
  { a: ['apple', 'ant'], b: ['bee'] }
);

assert.deepStrictEqual(groupBy([], (x) => x), {});

// order preserved within groups
assert.deepStrictEqual(
  groupBy([3, 1, 4, 1, 5], (n) => (n % 2 === 0 ? 'even' : 'odd')),
  { odd: [3, 1, 1, 5], even: [4] }
);

// consumed by stats.sizes
assert.deepStrictEqual(sizes(['apple', 'ant', 'bee'], (w) => w[0]), { a: 2, b: 1 });

console.log('ok');

