function groupBy(items, keyOf) {
  const out = {};
  for (const item of items) {
    const key = keyOf(item);
    if (!Object.prototype.hasOwnProperty.call(out, key)) {
      out[key] = [];
    }
    out[key].push(item);
  }
  return out;
}

module.exports = { groupBy };

