function groupBy(items, keyOf) {
  // BUG: assigns a fresh single-element array each time, so each key keeps
  // only its LAST item instead of accumulating.
  const out = {};
  for (const item of items) {
    out[keyOf(item)] = [item];
  }
  return out;
}

module.exports = { groupBy };
